scaleCheckBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "scaleCheckBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "psyWiz",
                name = "scaleCheck",
                version = c(1,0,0),
                options = options,
                results = scaleCheckResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Scale Check
#'
#' Checks one scale: reliability (alpha, lambda-2, omega, AVE), whether the 
#' items are congeneric, tau-equivalent or parallel (which decides whether 
#' alpha and unit-weighted sum scores are justified), item statistics, and 
#' Guttman / Mokken scalability.
#' 
#'
#' @examples
#' \donttest{
#' data('wizdata', package = 'psyWiz')
#' psyWiz::scaleCheck(wizdata, vars = c('trust1', 'trust2', 'trust3', 'trust4'), run = TRUE)
#'}
#' @param data the data as a data frame
#' @param vars a vector of strings naming the items of the scale
#' @param scaleName a string, the name of the scale
#' @param run \code{TRUE} or \code{FALSE} (default), fit the models; while
#'   \code{FALSE} only a summary of the plan is shown
#' @param type \code{'auto'} (default; ordinal variables are treated as
#'   ordinal, continuous ones as continuous), \code{'ordinal'} or
#'   \code{'continuous'}
#' @param estimator \code{'auto'} (default; MLR for continuous items, WLSMV
#'   for ordinal items), \code{'ML'}, \code{'MLR'}, \code{'MLM'},
#'   \code{'WLSMV'}, \code{'ULSMV'}, \code{'DWLS'} or \code{'ULS'}
#' @param missing \code{'auto'} (default; FIML for ML and MLR, pairwise
#'   deletion for ordinal items), \code{'listwise'}, \code{'fiml'} or
#'   \code{'pairwise'}
#' @param parallel \code{TRUE} (default) or \code{FALSE}, fit the models
#'   concurrently when one takes more than a second
#' @param useCfi \code{TRUE} (default) or \code{FALSE}, use the change in CFI
#'   for the verdict
#' @param cutCfi a number (default 0.010), the largest acceptable drop in CFI
#' @param useRmsea \code{TRUE} (default) or \code{FALSE}, use the change in
#'   RMSEA for the verdict
#' @param cutRmsea a number (default 0.015), the largest acceptable rise in
#'   RMSEA
#' @param useSrmr \code{TRUE} or \code{FALSE} (default), use the change in
#'   SRMR for the verdict
#' @param cutSrmrLoad a number (default 0.030), the largest acceptable rise in
#'   SRMR at the step that constrains loadings
#' @param cutSrmr a number (default 0.010), the largest acceptable rise in
#'   SRMR at the other steps
#' @param useChisq \code{TRUE} or \code{FALSE} (default), use the chi-square
#'   difference test for the verdict
#' @param alpha a number (default 0.05), the significance level of the
#'   difference test
#' @param showItems \code{TRUE} (default) or \code{FALSE}, show the item table
#' @param showScal \code{TRUE} (default) or \code{FALSE}, show Loevinger's H
#'   and the Guttman scalogram statistics
#' @param showDiagram \code{TRUE} or \code{FALSE} (default), draw the
#'   congeneric model
#' @param diagramStyle \code{'comb'} (teeth whose length is the variance an
#'   item shares with its factor), \code{'diagram'} (path diagram, arrow width
#'   proportional to the loading) or \code{'tiles'} (path diagram with a square
#'   per item filled in proportion to R-squared)
#' @param highlight \code{TRUE} or \code{FALSE} (default), show flagged
#'   changes in fit, weak loadings (below 0.40) and unscalable items (H below
#'   0.30) in red
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reliability} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$fit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$comparison} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$items} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$scalability} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$diagram} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$reliability$asDF}
#'
#' \code{as.data.frame(results$reliability)}
#'
#' @export
scaleCheck <- function(
    data,
    vars,
    scaleName = "Scale",
    run = FALSE,
    type = "auto",
    estimator = "auto",
    missing = "auto",
    parallel = TRUE,
    useCfi = TRUE,
    cutCfi = 0.01,
    useRmsea = TRUE,
    cutRmsea = 0.015,
    useSrmr = FALSE,
    cutSrmrLoad = 0.03,
    cutSrmr = 0.01,
    useChisq = FALSE,
    alpha = 0.05,
    showItems = TRUE,
    showScal = TRUE,
    showDiagram = FALSE,
    diagramStyle = "comb",
    highlight = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("scaleCheck requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- scaleCheckOptions$new(
        vars = vars,
        scaleName = scaleName,
        run = run,
        type = type,
        estimator = estimator,
        missing = missing,
        parallel = parallel,
        useCfi = useCfi,
        cutCfi = cutCfi,
        useRmsea = useRmsea,
        cutRmsea = cutRmsea,
        useSrmr = useSrmr,
        cutSrmrLoad = cutSrmrLoad,
        cutSrmr = cutSrmr,
        useChisq = useChisq,
        alpha = alpha,
        showItems = showItems,
        showScal = showScal,
        showDiagram = showDiagram,
        diagramStyle = diagramStyle,
        highlight = highlight)

    analysis <- scaleCheckClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

